function redeemFiatRequest(uint256 amountMTokenIn)
        external
        whenFnNotPaused(this.redeemFiatRequest.selector)
        returns (
            uint256 /*requestId*/
        )
    {
        _validateUserAccess(msg.sender);

        (
            uint256 requestId,
            CalcAndValidateRedeemResult memory calcResult
        ) = _redeemRequest(
                MANUAL_FULLFILMENT_TOKEN,
                amountMTokenIn,
                true,
                msg.sender
            );

        emit RedeemRequest(
            requestId,
            msg.sender,
            MANUAL_FULLFILMENT_TOKEN,
            amountMTokenIn,
            calcResult.feeAmount
        );

        return requestId;
    }

function cancelRedemption(
        address vault,
        uint256 queueIndex
    ) external override nonReentrant {

        // Validate and get redemption entry
        RedemptionQueueEntry memory entry = _validateAndGetRedemptionEntry(vault, queueIndex, true);

        // Spend allowance if caller is not the owner (before unlocking shares)
        if (entry.owner != msg.sender) {
            IVault(vault).spendAllowance(entry.owner, msg.sender, entry.lockedShares);
        }

        // Unlock shares for the owner (shares belong to owner, not necessarily msg.sender)
        IVault(vault).unlockShares(entry.owner, entry.lockedShares);

        // Update Standard Debt: SD = SD - lockedShares
        if (standardDebt[vault] < entry.lockedShares) {
            standardDebt[vault] = 0;
        } else {
            standardDebt[vault] = MathLib.safeSub(standardDebt[vault], entry.lockedShares);
        }

        // Remove from queue (delete entry, keep index unique)
        delete redemptionQueues[vault][queueIndex];

        emit RedemptionCancelled(vault, entry.owner, queueIndex, entry.lockedShares, entry.receiver);
    }

function redeemFromValidators(uint256 ethersToRedeem, uint256 maxToBurn, uint256 deadline)
        external
        nonReentrant
        whenRedeemEnabled
        returns (uint256 burned)
    {
        _require(block.timestamp < deadline, "USR001");
        _require(ethersToRedeem % DEPOSIT_SIZE == 0, "USR005");
        _require(ethersToRedeem > 0, "USR005");

        uint256 totalXETH = IERC20(xETHAddress).totalSupply();
        uint256 xETHToBurn = totalXETH * ethersToRedeem / currentReserve();
        _require(xETHToBurn <= maxToBurn, "USR004");

        // NOTE: the following procdure must keep exchangeRatio invariant:
        // transfer xETH from sender & burn
        // uint256 ratio = _exchangeRatioInternal();           // RATIO GUARD BEGIN
        IMintableContract(xETHAddress).burnFrom(msg.sender, xETHToBurn);
        _enqueueDebt(msg.sender, ethersToRedeem); // queue ether debts
        // assert(ratio == _exchangeRatioInternal());          // RATIO GUARD END

        // return burned
        return xETHToBurn;
    }

